package lk.repairdesk.api.service; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.dto.RepairDtos.*; import lk.repairdesk.api.exception.ResourceNotFoundException; import lk.repairdesk.api.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class RepairService {private final RepairRequestRepository repo;private final DeviceService devices;private final CurrentUserService current;private final UserRepository users;public RepairService(RepairRequestRepository r,DeviceService d,CurrentUserService c,UserRepository u){repo=r;devices=d;current=c;users=u;} @Transactional public Response create(CreateRequest x){var r=new RepairRequest();r.setDevice(devices.owned(x.deviceId()));r.setCustomer(current.get());r.setTitle(x.title().trim());r.setDescription(x.description().trim());r.setPriority(x.priority());r.setEstimatedValue(x.estimatedValue());return map(repo.save(r));} @Transactional(readOnly=true) public Page<Response> search(RepairStatus status,String q,Pageable p){var u=current.get();Long customer=u.getRole()==Role.CUSTOMER?u.getId():null;return repo.search(status,customer,(q==null||q.isBlank())?null:q.trim(),p).map(this::map);} @Transactional public Response assign(Long id,AssignTechnician x){var r=get(id);var t=users.findById(x.technicianId()).orElseThrow(()->new ResourceNotFoundException("Technician not found"));if(t.getRole()!=Role.TECHNICIAN)throw new IllegalArgumentException("Selected user is not a technician");r.setTechnician(t);r.setStatus(RepairStatus.ASSIGNED);return map(r);} @Transactional public Response status(Long id,UpdateStatus x){var r=get(id);r.setStatus(x.status());return map(r);} public RepairRequest get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Repair request not found"));} public Response map(RepairRequest r){var t=r.getTechnician();return new Response(r.getId(),r.getDevice().getId(),r.getDevice().getBrand()+" "+r.getDevice().getModel(),r.getCustomer().getId(),r.getCustomer().getName(),t==null?null:t.getId(),t==null?null:t.getName(),r.getTitle(),r.getDescription(),r.getPriority(),r.getStatus(),r.getEstimatedValue(),r.getCreatedAt(),r.getUpdatedAt());}}